def transform(grid):
    # A central separator (2 for the 4-row task, 6 in the other demos)
    # divides two panels. Keep the left panel pattern as the output's 3s;
    # color the corresponding panel background with the panel's background.
    sep = next(c for c in range(len(grid[0])) if all(row[c] == 2 for row in grid))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    h, w = len(grid), sep
    bg = max(set(v for row in left for v in row), key=lambda v: sum(x == v for row in left for x in row))
    out = [[3 if left[r][c] != bg else 7 for c in range(w)] for r in range(h)]
    # The right pattern selects locations to preserve as 3; other left cells are 7.
    for r in range(h):
        for c in range(w):
            if c < len(right[r]) and right[r][c] == 0 and left[r][c] != bg:
                out[r][c] = 3
    return out

